rep.push('下载检测('+lg.length+'):\n'+dt.join('\n'));
}else{rep.push('下载检测: 暂无记录');}}catch(e){}
if(bad){try{java.log('Z-Library 自检异常：\n'+rep.join('\n'));}catch(e){}}
var out=[];
if(!loginOK){out.push('—— 请先登录 ——');}
else if(!sOK||!dOK||!cOK){out.push('—— 有异常 ——');}
else{out.push('—— 全部正常 ——');}
