function login() {
    java.log("模拟登录请求");
    cookie.removeCookie(source.key)
    res = source.getLoginInfoMap()

    use=res.get("帐号");
    pwd=res.get("密码");

    code=java.getVerificationCode("https://www.qf917.com/code.jpg?"+Math.random())

    body=`user_name=${use}&user_pass=${java.md5Encode(pwd)}&user_code=${code}`

   headers= {
    "accept": "*/*",
    "accept-language": "zh-CN,zh;q=0.9",
    "cache-control": "no-cache",
    "content-type": "application/x-www-form-urlencoded; charset=UTF-8",
    "pragma": "no-cache",
    "x-requested-with": "XMLHttpRequest",
    "Referer": "https://www.qf917.com",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "User-Agent": "Mozilla/5.0 (Linux; Android 15; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/133.0.0.9 Mobile Safari/537.36"
  }
    html=java.ajax("https://www.qf917.com/qs_login_go.php,"+JSON.stringify({
  "body": body,
  "method": "POST",
  "headers": JSON.stringify(headers)
    	}))

    java.longToast(html)
    Packages.java.lang.Thread.sleep(1000)

}

ruleToc.chapterList:
@js:
let v = [],
		list = [];
JSON.parse(result).list.map($=>{

//分卷判定
		V = $.name;
		if(v[v.length-1]!=V&&!/^\s*$/.test(V)){
				v.push(V)
				list.push({
						name: '📖['+V+']📖',
						volume: true
					})
			}

$.bookChapters.map($=>{
		return list.push({
				name: $.name,
				url: `https://readbook-service-freebook.cread.com/cx/itf/chapterRead?bookId=${$.bookid}&chapterId=${$.id}`,
				info: `章节字数：${$.wordCount}　更新时间：${$.updateDate}`
			});
	});
});
v.length<2?list.filter($=>!$.volume):list

